import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    try:
        savings_balance = int(data[0])
        current_balance = float(data[1])
        fixed_deposit_balance = float(data[2])
    except (IndexError, ValueError):
        return
    total = float(savings_balance) + current_balance + fixed_deposit_balance
    # Format to 2 decimal places as per samples
    print(f"Total Balance: {total:.2f}")

if __name__ == "__main__":
    main()
